do $$
declare n int; s numeric; g int; v int; a int;
begin
  select count(*), sum(price_ex_vat) into n, s from public.enquiries;
  select count(*) into g from public.enquiries where status = 'Gautas PO';
  select count(*) into v from public.enquiries where status = 'Vykdoma';
  select count(*) into a from public.enquiries where status = 'Atmesta užklausa';
